    [21134]={name="Dark Edge of Insanity",quality=4,ilvl=84,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped.",proc="Chance on hit: Disorients the target, causing it to wander aimlessly for up to 3 sec."},
    [21180]={name="Earthstrike",quality=4,ilvl=66,sourceType="quest_reward",instructions="Reward from the quest 'Champion's Battlegear'. Pick it over the other reward choices.",zone="Silithus",questName="Champion's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them.",proc="Use: Increases your melee and ranged attack power by 280.  Effect lasts for 20 sec. (2 Min Cooldown)"},
    [21186]={name="Rockfury Bracers",quality=4,ilvl=62,sourceType="quest_reward",instructions="Reward from the quest 'Stalwart's Battlegear'. Pick it over the other reward choices.",zone="Silithus",questName="Stalwart's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."},
    [21204]={name="Signet Ring of the Bronze Dragonflight",quality=4,ilvl=75,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Path of the Conqueror'.",zone="Tanaris",questName="The Path of the Conqueror"},
    [21372]={name="Stormcaller's Diadem",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Stormcaller's Diadem'.",zone="Ahn'Qiraj",questName="Stormcaller's Diadem",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21374]={name="Stormcaller's Hauberk",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Stormcaller's Hauberk'.",zone="Ahn'Qiraj",questName="Stormcaller's Hauberk",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21400]={name="Cloak of the Gathering Storm",quality=4,ilvl=67,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Cloak of the Gathering Storm'.",zone="Ahn'Qiraj",questName="Cloak of the Gathering Storm",lore="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj. I can make you a protective item that'll be of assistance in the fight against our enemy."},
